#include <sys/param.h>

#include "dm_ld2410b.h"

/****************************************************************************
 * Private Definitions
 ****************************************************************************/

#define LD2410B_DEV           "/dev/ttyS0"
#define LD2410B_BAUD          B115200

/* 帧结构（小端）：
 *   F4 F3 F2 F1 | len(2B) | 数据[len] | F8 F7 F6 F5
 *   数据内：type(1B) 0xAA 目标状态(1B) 运动距离(2B) 运动能量(1B)
 *           静止距离(2B) 静止能量(1B) 探测距离(2B) 0x55 0x00
 */
#define FRAME_HDR0            0xF4
#define FRAME_HDR1            0xF3
#define FRAME_HDR2            0xF2
#define FRAME_HDR3            0xF1
#define FRAME_TAIL0           0xF8
#define FRAME_TAIL1           0xF7
#define FRAME_TAIL2           0xF6
#define FRAME_TAIL3           0xF5

#define DATA_TYPE_BASIC       0x02   /* 目标基本信息数据 */
#define DATA_HEAD_AA          0xAA
#define DATA_TAIL_55          0x55

#define FRAME_MAX_LEN         128    /* 工程模式帧 < 64B，留余量 */

/* 解析状态机 */
enum
{
  ST_WAIT_HDR = 0,   /* 找 F4 F3 F2 F1 */
  ST_HDR1,           /* 已收 F4 */
  ST_HDR2,           /* 已收 F4 F3 */
  ST_HDR3,           /* 已收 F4 F3 F2 */
  ST_LEN_LO,         /* 已收 F4 F3 F2 F1 */
  ST_LEN_HI,
  ST_DATA,           /* 收帧内数据 len 字节 */
  ST_TAIL0,          /* 数据收完，等 F8 */
  ST_TAIL1,
  ST_TAIL2,
  ST_TAIL3,          /* 等 F5（收齐 = 一帧完成） */
};

/* 数据内字段偏移（数据区起点 = type 字节） */
#define OFF_TYPE       0
#define OFF_AA         1
#define OFF_STATE      2
#define OFF_MOVE_DIST  3   /* 2B LE */
#define OFF_MOVE_ENG   5
#define OFF_STAT_DIST  6   /* 2B LE */
#define OFF_STAT_ENG   8
#define OFF_DET_DIST   9   /* 2B LE */
#define OFF_TAIL_55    11
#define OFF_TAIL_00    12
#define DATA_LEN_BASIC 13  /* type..0x00 共 13B（len 字段值=0x0D） */

/****************************************************************************
 * Private Types
 ****************************************************************************/

/****************************************************************************
 * Private Data
 ****************************************************************************/

static pthread_t       g_ld2410b_thread;
static volatile bool   g_ld2410b_run;      /* 线程运行标志 */
static volatile bool   g_ld2410b_ready;    /* 串口已打开 */
static volatile int    g_ld2410b_state;    /* 最近一帧目标状态 */
static volatile int    g_ld2410b_dist_cm;  /* 最近一帧探测距离 */
static volatile int    g_ld2410b_frame_ok; /* 已成功解析过完整帧 */

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* 从解析帧数据区提取探测距离（小端） */
static int ld2410b_extract_dist(const uint8_t *d)
{
  return (int)(d[OFF_DET_DIST] | (d[OFF_DET_DIST + 1] << 8));
}

/* 串口读取线程：read → 状态机 → 提取目标状态/距离 */
static void *ld2410b_reader(void *arg)
{
  (void)arg;
  uint8_t  buf[64];
  uint8_t  frame[FRAME_MAX_LEN];
  int      fpos = 0;
  int      flen = 0;
  int      st   = ST_WAIT_HDR;

  while (g_ld2410b_run)
    {
      ssize_t n = read(0, buf, sizeof(buf)); /* fd 0 是假；真 fd 见下 */
      (void)n;
      break; /* 占位，实际 fd 在 init 传入 */
    }

  return NULL;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int dm_ld2410b_init(void)
{
  /* TODO: open /dev/ttyS0 + 状态机（下一步实现） */
  (void)LD2410B_DEV;
  (void)LD2410B_BAUD;
  (void)ld2410b_extract_dist;
  return -1;
}

int dm_ld2410b_get_state(void)
{
  return (int)g_ld2410b_state;
}

int dm_ld2410b_get_dist_cm(void)
{
  if (!g_ld2410b_frame_ok)
    return -1;
  return (int)g_ld2410b_dist_cm;
}

int dm_ld2410b_present(void)
{
  if (!g_ld2410b_ready)
    return -1;
  return LD2410B_STATE_PRESENT(g_ld2410b_state) ? 1 : 0;
}

