/****************************************************************************
 * dm_health.c 调用：人体感应距离 cm
 * 2026-08-23：数据源从 LTR553 接近传感器切换为 LD2410B 毫米波雷达。
 *   - 有人（状态≠NONE）且 探测距离 ≤ ld2410_seat_cm（默认 200cm）→ 返回 0
 *     （≤30cm 判据通过 = 在座）
 *   - 有人但超出阈值 / 无人 → 返回 99（>30cm 判据 = 离开）
 *   - LD2410B 串口不可用 → -1（dm_health 回退纯计时模式）
 ****************************************************************************/
int dm_prox_get_cm(void)
{
    int state = dm_ld2410b_get_state();
    int dist;

    if (!dm_ld2410b_present())
    {
        if (dm_ld2410b_get_dist_cm() < 0 && !dm_ld2410b_present())
            return -1;   /* 串口未就绪/无数据：回退纯计时 */
        return 99;       /* 无人：离开 */
    }

    dist = dm_ld2410b_get_dist_cm();
    if (dist >= 0 && dist <= 200)
        return 0;        /* 有人且在座距离内：在座 */
    return 99;           /* 有人但超出阈值 / 距离未知：离开 */
}

