114	  if (d[11] != DATA_TAIL_55 || d[12] != 0x00)
115	    return -1;                       /* 数据区尾部校验失败 */
116	
117	  g_ld2410b_state   = d[OFF_STATE];
118	  g_ld2410b_dist_cm = ld2410b_le16(&d[OFF_DET_DIST]);
119	  g_ld2410b_frame_ok = true;
120	  return 0;
121	}
