123	/* 串口读取线程：read → 状态机 → 提取目标状态/距离 */
124	static void *ld2410b_reader(void *arg)
125	{
126	  int      fd = (int)(intptr_t)arg;
127	  uint8_t  buf[64];
128	  uint8_t  frame[FRAME_MAX_LEN];
129	  int      fpos = 0;
130	  int      flen = 0;
131	  int      st   = ST_WAIT_HDR;
132	
133	  while (g_ld2410b_run)
134	    {
135	      ssize_t n = read(fd, buf, sizeof(buf));
136	      if (n <= 0)
137	        {
138	          if (n < 0 && errno != EAGAIN)
139	            usleep(100 * 1000);      /* 错误退避，防忙转 */
140	          continue;
141	        }
142	
143	      for (ssize_t i = 0; i < n; i++)
144	        {
145	          uint8_t b = buf[i];
146	
147	          switch (st)
148	            {
149	            case ST_WAIT_HDR:
150	              if (b == FRAME_HDR0) st = ST_HDR1;
151	              break;
152	            case ST_HDR1:
153	              st = (b == FRAME_HDR1) ? ST_HDR2 : ST_WAIT_HDR;
154	              break;
155	            case ST_HDR2:
156	              st = (b == FRAME_HDR2) ? ST_HDR3 : ST_WAIT_HDR;
157	              break;
158	            case ST_HDR3:
159	              st = (b == FRAME_HDR3) ? ST_LEN_LO : ST_WAIT_HDR;
160	              break;
161	            case ST_LEN_LO:
162	              flen = b;
163	              st   = ST_LEN_HI;
164	              break;
165	            case ST_LEN_HI:
166	              flen |= (b << 8);
167	              if (flen < DATA_LEN_BASIC || flen > FRAME_MAX_LEN)
168	                {
169	                  st = ST_WAIT_HDR;  /* 长度非法，重新找头 */
170	                }
171	              else
172	                {
173	                  fpos = 0;
174	                  st   = ST_DATA;
175	                }
176	              break;
177	            case ST_DATA:
178	              frame[fpos++] = b;
179	              if (fpos >= flen)
180	                st = ST_TAIL0;
181	              break;
182	            case ST_TAIL0:
183	              st = (b == FRAME_TAIL0) ? ST_TAIL1 : ST_WAIT_HDR;
184	              break;
185	            case ST_TAIL1:
186	              st = (b == FRAME_TAIL1) ? ST_TAIL2 : ST_WAIT_HDR;
187	              break;
188	            case ST_TAIL2:
189	              st = (b == FRAME_TAIL2) ? ST_TAIL3 : ST_WAIT_HDR;
190	              break;
191	            case ST_TAIL3:
192	              if (b == FRAME_TAIL3)
193	                {
194	                  ld2410b_parse_frame(frame, flen);   /* 一帧收齐 */
195	                }
196	              st = ST_WAIT_HDR;
197	              break;
198	            default:
199	              st = ST_WAIT_HDR;
200	              break;
201	            }
202	        }
203	    }
204	
205	  close(fd);
206	  return NULL;
207	}
