234	    }
235	  cfmakeraw(&tio);
236	  cfsetispeed(&tio, LD2410B_BAUD);
237	  cfsetospeed(&tio, LD2410B_BAUD);
238	  tio.c_cflag |= (CLOCAL | CREAD);
239	  if (tcsetattr(fd, TCSANOW, &tio) < 0)
240	    {
241	      close(fd);
242	      return -1;
243	    }
244	
245	  g_ld2410b_run = true;
246	  if (pthread_create(&g_ld2410b_thread, NULL, ld2410b_reader,
247	                     (void *)(intptr_t)fd) != 0)
248	    {
249	      close(fd);
250	      g_ld2410b_run = false;
251	      return -1;
252	    }
253	
254	  g_ld2410b_ready = true;
255	  LV_LOG_INFO("[ld2410b] init ok (%s @115200)", LD2410B_DEV);
256	  return 0;
257	}
